namespace BlazorNotifications.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.Add(new Notification(_nextId++, "Welcome to the notification center!", DateTime.Now.AddMinutes(-10)));
        _notifications.Add(new Notification(_nextId++, "Your profile was updated successfully.", DateTime.Now.AddMinutes(-5)));
        _notifications.Add(new Notification(_nextId++, "New feature: Dark mode is now available.", DateTime.Now.AddMinutes(-2)));
    }

    /// <summary>
    /// Gets all notifications available up to this point.
    /// </summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    /// <summary>
    /// Gets only notifications newer than the given ID (for polling).
    /// </summary>
    public List<Notification> GetNewerThan(int lastSeenId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > lastSeenId).ToList();
        }
    }

    /// <summary>
    /// Simulates new notifications arriving over time.
    /// Called internally to generate fake data.
    /// </summary>
    public void SimulateIncoming()
    {
        var messages = new[]
        {
            "You have a new follower!",
            "Your report is ready to download.",
            "Scheduled maintenance tonight at 11 PM.",
            "Someone commented on your post.",
            "Your subscription will renew soon.",
            "A new version of the app is available.",
            "Security alert: new login from unknown device.",
        };

        lock (_lock)
        {
            var msg = messages[(_nextId - 1) % messages.Length];
            _notifications.Add(new Notification(_nextId++, msg, DateTime.Now));
        }
    }
}

